#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "syr2k.h"


/* Array initialization. */
static
void init_array(int n, int m,
		DATA_TYPE *alpha,
		DATA_TYPE *beta,
		DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		DATA_TYPE POLYBENCH_2D(B,N,M,n,m))
{
  int i, j;

  *alpha = 1.5;
  *beta = 1.2;
  for (i = 0; i < n; i++)
    for (j = 0; j < m; j++) {
      A[i][j] = (DATA_TYPE) ((i*j+1)%n) / n;
      B[i][j] = (DATA_TYPE) ((i*j+2)%m) / m;
    }
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      C[i][j] = (DATA_TYPE) ((i*j+3)%n) / m;
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(C,N,N,n,n))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("C");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
	if ((i * n + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, C[i][j]);
    }
  POLYBENCH_DUMP_END("C");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations applied:
   - Loop reordering so that, for each (i,j), the full dot-product over k
     is computed while keeping C[i][j] in a register. This reduces the
     number of loads/stores of C by a factor of ~M.
   - Introduction of local restrict-qualified row pointers to help the
     compiler with alias analysis and to expose the row-major layout.
   - Inner loop over k is the innermost loop: this gives unit-stride
     accesses in the reduction dimension and is friendly to vectorization.
   - Simple scalar temporaries are used to hoist repeated loads.
*/
static
void __attribute__((noinline, flatten))
kernel_syr2k(int n, int m,
		  DATA_TYPE alpha,
		  DATA_TYPE beta,
		  DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		  DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		  DATA_TYPE POLYBENCH_2D(B,N,M,n,m))
{
  int i, j, k;

  /* Local restrict-qualified pointers for better alias analysis.
     In PolyBench, A, B, and C are distinct contiguous buffers, so
     this faithfully describes the actual aliasing behavior. */
  DATA_TYPE (*restrict C_)[n] = C;
  DATA_TYPE (*restrict A_)[m] = A;
  DATA_TYPE (*restrict B_)[m] = B;

  const DATA_TYPE alpha_local = alpha;
  const DATA_TYPE beta_local  = beta;

//BLAS PARAMS
//UPLO  = 'L'
//TRANS = 'N'
//A is NxM
//B is NxM
//C is NxN
#pragma scop
  /* Reordered loops:
     Original structure (simplified):
       for i
         for j<=i: C[i][j] *= beta;
         for k
           for j<=i: C[i][j] += ...

     New structure:
       for i
         for j<=i
           cij = beta * C[i][j];
           for k: cij += ...
           C[i][j] = cij;

     This keeps each C[i][j] in a register across the whole reduction
     over k, greatly reducing memory traffic on C while preserving
     the mathematical result. */
  for (i = 0; i < _PB_N; i++)
  {
    DATA_TYPE *restrict Ci             = C_[i];
    const DATA_TYPE *restrict Ai_row   = A_[i];
    const DATA_TYPE *restrict Bi_row   = B_[i];

    for (j = 0; j <= i; j++)
    {
      DATA_TYPE cij = Ci[j] * beta_local;

      const DATA_TYPE *restrict Aj_row = A_[j];
      const DATA_TYPE *restrict Bj_row = B_[j];

      /* Reduction over k: perfectly vectorizable, unit-stride accesses. */
#pragma GCC ivdep
      for (k = 0; k < _PB_M; k++)
      {
        const DATA_TYPE a_jk = Aj_row[k];
        const DATA_TYPE b_jk = Bj_row[k];
        const DATA_TYPE a_ik = Ai_row[k];
        const DATA_TYPE b_ik = Bi_row[k];

        /* Form:
           C[i][j] += alpha * (A[j][k] * B[i][k] + B[j][k] * A[i][k]);
           Factoring alpha outside keeps the operation count low and
           allows fused operations on modern CPUs. */
        cij += alpha_local * (a_jk * b_ik + b_jk * a_ik);
      }

      Ci[j] = cij;
    }
  }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,N,N,n,n);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,N,M,n,m);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,N,M,n,m);

  /* Initialize array(s). */
  init_array (n, m, &alpha, &beta,
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_syr2k (n, m,
		alpha, beta,
		POLYBENCH_ARRAY(C),
		POLYBENCH_ARRAY(A),
		POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(C)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}
