  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
	if ((i * n + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, C[i][j]);
    }
  POLYBENCH_DUMP_END("C");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_syr2k[[gnu::flatten, gnu::noinline]](int n, int m,
		  DATA_TYPE alpha,
		  DATA_TYPE beta,
		  DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		  DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		  DATA_TYPE POLYBENCH_2D(B,N,M,n,m))
{
  int i, j, k;

  /* Create restrict-qualified local aliases.  This explicitly tells
   * the compiler that A, B and C do not alias, which enables more
   * aggressive reordering, vectorization, and register allocation.
   * The PolyBench harness allocates these arrays separately, so the
   * no-alias assumption is valid.
   */
  DATA_TYPE       (*restrict C_)[n] = C;
  const DATA_TYPE (*restrict A_)[m] = A;
  const DATA_TYPE (*restrict B_)[m] = B;

  const DATA_TYPE alpha_local = alpha;
  const DATA_TYPE beta_local  = beta;

  /* Temporary arrays:
   *   alpha_Ai[k] = alpha * A[i][k]
   *   alpha_Bi[k] = alpha * B[i][k]
   *
   * They are allocated once on the stack and reused for each i.
   * This avoids recomputing alpha*A[i][k] and alpha*B[i][k] for
   * every (i,j,k) triplet, while still allowing an inner loop over k
   * for good memory locality.
   */
  DATA_TYPE alpha_Ai[m];
  DATA_TYPE alpha_Bi[m];

//BLAS PARAMS
//UPLO  = 'L'
//TRANS = 'N'
//A is NxM
//B is NxM
//C is NxN
#pragma scop
  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE       *restrict Ci = C_[i];
    const DATA_TYPE *restrict Ai = A_[i];
    const DATA_TYPE *restrict Bi = B_[i];

    /* Precompute factors that depend only on (i,k).  These values are
     * reused for all j <= i in the current row.
     */
    for (k = 0; k < _PB_M; k++) {
      alpha_Ai[k] = alpha_local * Ai[k];
      alpha_Bi[k] = alpha_local * Bi[k];
    }

    /* Process the lower-triangular part (including the diagonal) of
     * row i.
     *
     * Compared to the original kernel:
     *  - The beta scaling of C[i][j] is fused with the accumulation
     *    into a single read/modify/write of C[i][j].
     *  - The innermost loop now iterates over k, which means that
     *    A[j][k], B[j][k], A[i][k], and B[i][k] are all accessed
     *    along their fastest-varying (contiguous) dimension.
     *    This significantly improves cache locality and makes the
     *    loop easy to vectorize.
     *
     * Importantly, the order of operations that affect each individual
     * element C[i][j] is preserved:
     *   - We still apply the beta scaling exactly once.
     *   - We then accumulate contributions for k = 0 .. _PB_M-1 in
     *     increasing order.
     * Only iterations that touch different (i,j) pairs are reordered,
     * which is safe because those memory locations are independent.
     */
    for (j = 0; j <= i; j++) {
      const DATA_TYPE *restrict Aj = A_[j];
      const DATA_TYPE *restrict Bj = B_[j];

      /* Fuse "C[i][j] *= beta" with the subsequent sum over k. */
      DATA_TYPE cij = Ci[j] * beta_local;

      /* Rank-2k update for the (i,j) entry:
       *   C[i][j] += sum_k ( A[j][k] * alpha * B[i][k]
       *                    + B[j][k] * alpha * A[i][k] )
       * where alpha_Ai[k] = alpha * A[i][k] and
       *       alpha_Bi[k] = alpha * B[i][k].
       */
      for (k = 0; k < _PB_M; k++) {
        cij += Aj[k] * alpha_Bi[k] + Bj[k] * alpha_Ai[k];
      }

      Ci[j] = cij;
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,N,N,n,n);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,N,M,n,m);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,N,M,n,m);

  /* Initialize array(s). */
  init_array (n, m, &alpha, &beta,
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_syr2k (n, m,
		alpha, beta,
		POLYBENCH_ARRAY(C),
		POLYBENCH_ARRAY(A),
		POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(C)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}
