/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(C,N,N,n,n))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("C");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
	if ((i * n + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, C[i][j]);
    }
  POLYBENCH_DUMP_END("C");
  POLYBENCH_DUMP_FINISH;
}


/*
 * Main computational kernel. The whole function will be timed,
 * including the call and return.
 *
 * Optimization notes:
 * - The original version scaled C by beta in a first j-loop and then
 *   updated C in a k-j nested loop (i, then k, then j).
 * - Here we:
 *     * Give the compiler better aliasing information using restrict
 *       pointers for the three matrices (they do not alias in PolyBench).
 *     * Reorder the loops to i, j, k so that the innermost loop (k)
 *       walks contiguous memory in A and B (row-major), which greatly
 *       improves cache locality and enables efficient vectorization.
 *     * Keep the per-element operation order for a given (i,j): we still
 *       do "scale by beta, then accumulate over k in increasing order".
 *       Only the order in which different (i,j) pairs are processed changes.
 * - The mathematical operation is identical to the original:
 *     C[i][j] = beta * C[i][j]
 *               + sum_k ( A[j][k]*alpha*B[i][k] + B[j][k]*alpha*A[i][k] )
 *   on the lower triangle (i >= j).
 */
static
void kernel_syr2k[[gnu::flatten, gnu::noinline]](int n, int m,
		  DATA_TYPE alpha,
		  DATA_TYPE beta,
		  DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		  DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		  DATA_TYPE POLYBENCH_2D(B,N,M,n,m))
{
  int i, j, k;

  /* Local copies help the compiler keep these in registers. */
  const DATA_TYPE alpha_local = alpha;
  const DATA_TYPE beta_local  = beta;

  /*
   * Provide the compiler with non-aliasing information between A, B, and C.
   * PolyBench allocates A, B, and C as separate buffers, so this is valid.
   * We only use these restrict-qualified pointers inside the kernel.
   */
  DATA_TYPE       (*restrict C_r)[N] = (DATA_TYPE       (*restrict)[N])C;
  const DATA_TYPE (*restrict A_r)[M] = (const DATA_TYPE (*restrict)[M])A;
  const DATA_TYPE (*restrict B_r)[M] = (const DATA_TYPE (*restrict)[M])B;

//BLAS PARAMS
//UPLO  = 'L'
//TRANS = 'N'
//A is NxM
//B is NxM
//C is NxN
#pragma scop
  for (i = 0; i < _PB_N; i++)
  {
    /* Pointers to the current row i of C, A, and B.
     * Accessing Ci[j] is equivalent to C[i][j] but saves index arithmetic.
     */
    DATA_TYPE       *Ci = C_r[i];
    const DATA_TYPE *Ai = A_r[i];
    const DATA_TYPE *Bi = B_r[i];

    /* Only the lower triangle (j <= i) is updated. */
    for (j = 0; j <= i; j++)
    {
      const DATA_TYPE *Aj = A_r[j];
      const DATA_TYPE *Bj = B_r[j];

      /* Start from beta * C[i][j], as in the original code. */
      DATA_TYPE cij = Ci[j] * beta_local;

      /* Inner product along k over rows i and j of A and B.
       * The k-loop is now innermost, providing unit-stride access to
       * Ai[k], Bi[k], Aj[k], Bj[k] and enabling efficient vectorization.
       */
#pragma GCC ivdep
      for (k = 0; k < _PB_M; k++)
      {
        const DATA_TYPE aik = Ai[k];
        const DATA_TYPE bik = Bi[k];
        const DATA_TYPE ajk = Aj[k];
        const DATA_TYPE bjk = Bj[k];

        /* Keep the same algebraic form as the original code:
         * A[j][k]*alpha*B[i][k] + B[j][k]*alpha*A[i][k]
         * (operand evaluation order for each term is preserved).
         */
        cij += ajk * alpha_local * bik
             + bjk * alpha_local * aik;
      }

      Ci[j] = cij;
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,N,N,n,n);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,N,M,n,m);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,N,M,n,m);

  /* Initialize array(s). */
  init_array (n, m, &alpha, &beta,
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_syr2k (n, m,
		alpha, beta,
		POLYBENCH_ARRAY(C),
		POLYBENCH_ARRAY(A),
		POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(C)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}
