/* Main computational kernel. The whole function will be timed,
   including the call and return.
 *
 * Optimizations applied:
 *  - Introduce restrict-qualified local aliases for A, B, and C to
 *    allow the compiler to assume no aliasing between them.
 *  - Change loop order from (i, j scale; i, k, j update) to (i, j, k)
 *    so that each C[i][j] element is:
 *        * Loaded once,
 *        * Scaled by beta,
 *        * Accumulated over all k entirely in a scalar register,
 *        * Stored back once.
 *    This greatly reduces memory traffic to C and keeps the innermost
 *    loop purely over k, which accesses rows of A and B contiguously
 *    (good for caches and SIMD).
 *  - The mathematical result is identical to the original kernel
 *    (up to floating-point round-off differences) because the
 *    operations for each (i, j) are simply reassociated.
 */
static
void kernel_syr2k[[gnu::flatten, gnu::noinline]](int n, int m,
		  DATA_TYPE alpha,
		  DATA_TYPE beta,
		  DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		  DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		  DATA_TYPE POLYBENCH_2D(B,N,M,n,m))
{
  int i, j, k;

  /* Local restrict-qualified aliases improve alias analysis. */
  DATA_TYPE       (*restrict C_)[n] = C;
  const DATA_TYPE (*restrict A_)[m] = A;
  const DATA_TYPE (*restrict B_)[m] = B;

  const DATA_TYPE alpha_local = alpha;
  const DATA_TYPE beta_local  = beta;

//BLAS PARAMS
//UPLO  = 'L'
//TRANS = 'N'
//A is NxM
//B is NxM
//C is NxN
#pragma scop
  for (i = 0; i < _PB_N; i++) {

    /* Pointers to the current row of C, A, and B. */
    DATA_TYPE       *restrict Ci_row = C_[i];
    const DATA_TYPE *restrict Ai_row = A_[i];
    const DATA_TYPE *restrict Bi_row = B_[i];

    /* Only the lower triangle (j <= i) is updated. */
    for (j = 0; j <= i; j++) {
      const DATA_TYPE *restrict Aj_row = A_[j];
      const DATA_TYPE *restrict Bj_row = B_[j];

      /* Start from beta * C[i][j] ... */
      DATA_TYPE cij = beta_local * Ci_row[j];

      /* ... and accumulate all rank-2k contributions into 'cij'. */
      for (k = 0; k < _PB_M; k++) {
        /* Row-major accesses: Aj_row[k], Bj_row[k], Ai_row[k], Bi_row[k]
           are all contiguous along k, which is good for cache and SIMD. */
        cij += alpha_local *
               (Aj_row[k] * Bi_row[k] +
                Bj_row[k] * Ai_row[k]);
      }

      /* Final value for this element of the lower triangular part. */
      Ci_row[j] = cij;
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,N,N,n,n);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,N,M,n,m);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,N,M,n,m);

  /* Initialize array(s). */
  init_array (n, m, &alpha, &beta,
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_syr2k (n, m,
		alpha, beta,
		POLYBENCH_ARRAY(C),
		POLYBENCH_ARRAY(A),
		POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(C)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}
